 constructor(data,hooks){this.data=data;this.hooks=hooks;this.scene=new T.Scene();this.materials=new Map();this.geometries=new Map();this.actors=[];this.animals=[];this.lights=[];this.moving=[];this.clouds=[];this.birds=[];this.boats=[];this.shells=[];this.pickables=[];this.islands=[];this.reduced=false;this.visible=true;this.quality=innerWidth<600?'low':'high';this.dayMode='day';this.phase=12;this.lightPhase=12;this.film=null;this.time=0;this.clock=new T.Clock();this.lowFrames=0;this.ray=new T.Raycaster();this.pointer=new T.Vector2();this.home=V(42,39,48);this.homeTarget=V(0,0,0);this.actorTalking=null;this.keys=new Set();this.bounds=[]}
 mat(color,opts={}){const key=String(color)+JSON.stringify(opts);if(!this.materials.has(key))this.materials.set(key,new T.MeshStandardMaterial({color:palette[color]??color,flatShading:true,roughness:.85,...opts}));return this.materials.get(key)}
