 flowers(g,x,z,i){const p=this.group(g,V(x,0,z));this.box(p,'wood',0,.08,0,1.7,.16,1.3);this.box(p,'dark',0,.16,0,1.5,.1,1.1);for(let j=0;j<12;j++){const xx=(j%4)*.37-.55,zz=Math.floor(j/4)*.35-.35;this.cyl(p,'leaf',xx,.34,zz,.025,.4,undefined,5);this.ball(p,['gold','pink','lavender'][(j+i)%3],xx,.6,zz,.16,.13,.16)}}
 fence(g,x,z){for(let j=0;j<5;j++)this.box(g,'cream',x+j*.4,.4,z,.1,.8,.1);this.box(g,'cream',x+.8,.42,z,1.8,.1,.1)}
 bench(g,x,z){this.box(g,'wood',x,.45,z,1.2,.13,.45);this.box(g,'wood',x,.8,z-.2,1.2,.5,.1);for(const dx of [-.45,.45])this.box(g,'dark',x+dx,.23,z,.1,.46,.35)}
 sign(g,x,z,i){this.box(g,'wood',x,.6,z,.1,1.2,.12);this.box(g,i%2?'gold':'blue',x,1.1,z,.8,.55,.12)}
